#include "TestSupport.h"
#include "../src/Quest/QuestSystem.h"
#include "../src/Quest/QuestDefinitionDatabase.h"
#include "../src/Inventory/Inventory.h"
int main(){TestContext t;auto*d=QuestDefinitionDatabase::TryGet(QuestId::GATHERING_BASICS);t.Expect(d&&d->requiredAmount==10&&d->objectiveItem==ItemType::LOG&&d->rewardAmount==10,"Gathering Basics definition is stable");QuestJournal j;t.Expect(QuestSystem::Accept(j)&&!QuestSystem::Accept(j),"Accept exactly once");t.Expect(!QuestSystem::RecordGathered(j,ItemType::OAK_LOG)&&!QuestSystem::RecordGathered(j,ItemType::WILLOW_LOG),"Only normal Logs count");for(int progress=1;progress<=10;++progress)t.Expect(QuestSystem::RecordGathered(j,ItemType::LOG)&&j.Get().progress==progress,"Each successful normal Log increments progress");t.Expect(j.Get().state==QuestState::READY_TO_COMPLETE&&j.Get().progress==10&&!QuestSystem::RecordGathered(j,ItemType::LOG),"Progress reaches ten, caps and transitions once");Inventory inventory;t.Expect(QuestSystem::Complete(j,inventory)&&inventory.GetItemAmount(ItemType::COINS)==10,"Completion grants ten Coins");t.Expect(!QuestSystem::Complete(j,inventory)&&inventory.GetItemAmount(ItemType::COINS)==10,"Reward cannot be claimed twice");QuestJournal fullJournal;fullJournal.Get()={QuestId::GATHERING_BASICS,QuestState::READY_TO_COMPLETE,10};Inventory full;for(int i=0;i<Inventory::SlotCount;++i)full.AddItem(ItemType::LOG,1);t.Expect(!QuestSystem::Complete(fullJournal,full)&&fullJournal.Get().state==QuestState::READY_TO_COMPLETE&&full.GetItemAmount(ItemType::COINS)==0,"Atomic reward failure preserves readiness");return t.Finish();}
